import { type TeamHuntState } from "@hunt/public-client";
import React, { useMemo } from "react";
import { ErrataProvider } from "../components/ErrataContext";
import useDataset from "./useDataset";

export const ErrataDataProvider = ({
  initialTeamState,
  children,
}: {
  initialTeamState: TeamHuntState;
  children: React.ReactNode;
}) => {
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const errataKeys = useMemo(() => {
    return new Set(teamState.errata ?? []);
  }, [teamState.errata]);

  return <ErrataProvider errataKeys={errataKeys}>{children}</ErrataProvider>;
};
