import { type ActivityLogEntry } from "@hunt/public-client";
import { useEffect, useRef } from "react";
import {
  GATE_TO_FLAG_MAP,
  GATES_PER_ZONE,
  INTERACTIONS_PER_ZONE,
  INTERACTION_TO_FLAG_MAP,
} from "../../rounds/overworld/gameworld/common/constants";
import { CUSTOM_EVENTS } from "../../rounds/overworld/gameworld/common/event-bus";
import {
  type InteractionEventDetail,
  type GateCompletedEventDetail,
} from "../../rounds/overworld/gameworld/common/types";
import { useGameworldInteractionLog } from "../../rounds/overworld/gameworld/gameworldLocalState";

type InteractionStateManagerProps = {
  roundSlug: string;
};

type InteractionEventEntry = Extract<
  ActivityLogEntry,
  { type: "interaction_unlocked" | "interaction_completed" }
>;

type GateCompletedEventEntry = Extract<
  ActivityLogEntry,
  { type: "gate_completed" }
>;

type PuzzleProgressEventEntry = Extract<
  ActivityLogEntry,
  { type: "puzzle_unlockable" | "puzzle_unlocked" | "puzzle_solved" }
>;

const isInteractionEventEntry = (
  entry: ActivityLogEntry,
): entry is InteractionEventEntry & {
  slug: keyof typeof INTERACTION_TO_FLAG_MAP;
} => {
  if (
    entry.type !== "interaction_unlocked" &&
    entry.type !== "interaction_completed"
  ) {
    return false;
  }

  if (typeof entry.slug !== "string") {
    return false;
  }

  return Object.prototype.hasOwnProperty.call(
    INTERACTION_TO_FLAG_MAP,
    entry.slug,
  );
};

const isRelevantGateCompletedEntry = (
  entry: ActivityLogEntry,
): entry is GateCompletedEventEntry & {
  slug: keyof typeof GATE_TO_FLAG_MAP;
} => {
  if (entry.type !== "gate_completed") {
    return false;
  }

  if (typeof entry.slug !== "string") {
    return false;
  }

  return Object.prototype.hasOwnProperty.call(GATE_TO_FLAG_MAP, entry.slug);
};

const SPECIFIC_PUZZLE_UNLOCK_SLUG = "snalc_eht_tcennoc";

const isRoundUnlockedEntry = (
  entry: ActivityLogEntry,
): entry is ActivityLogEntry & {
  type: "round_unlocked";
  slug: string;
  title: string;
} => {
  return entry.type === "round_unlocked";
};

const isSpecificPuzzleUnlockedEntry = (
  entry: ActivityLogEntry,
): entry is ActivityLogEntry & {
  type: "puzzle_unlocked";
  slug: string;
  title: string;
} => {
  return (
    entry.type === "puzzle_unlocked" &&
    entry.slug === SPECIFIC_PUZZLE_UNLOCK_SLUG
  );
};

const isPuzzleProgressEntry = (
  entry: ActivityLogEntry,
): entry is PuzzleProgressEventEntry & {
  slug: string;
  title: string;
} => {
  return (
    entry.type === "puzzle_unlockable" ||
    entry.type === "puzzle_unlocked" ||
    entry.type === "puzzle_solved"
  );
};
// Interaction State Manager is responsible for updating the interaction state based on the activity log.
const InteractionStateManager = ({
  roundSlug,
}: InteractionStateManagerProps): null => {
  const processedIdsRef = useRef<Set<number>>(new Set());

  const activityLog = useGameworldInteractionLog();

  useEffect(() => {
    if (activityLog.length === 0) {
      return;
    }

    const relevantInteractionSlugs =
      INTERACTIONS_PER_ZONE[roundSlug as keyof typeof INTERACTIONS_PER_ZONE] ??
      [];

    const relevantGateSlugs =
      GATES_PER_ZONE[roundSlug as keyof typeof GATES_PER_ZONE] ?? [];

    const pendingEntries = activityLog
      .filter(
        (entry) =>
          !processedIdsRef.current.has(entry.id) &&
          (isInteractionEventEntry(entry) ||
            isRelevantGateCompletedEntry(entry) ||
            isRoundUnlockedEntry(entry) ||
            isSpecificPuzzleUnlockedEntry(entry) ||
            isPuzzleProgressEntry(entry)),
      )
      .sort((a, b) => a.id - b.id);

    pendingEntries.forEach((entry) => {
      if (isInteractionEventEntry(entry)) {
        const detail: InteractionEventDetail = {
          roundSlug,
          interactionSlug: entry.slug,
          title: entry.title,
          storyFlag: INTERACTION_TO_FLAG_MAP[entry.slug],
        };

        if (
          relevantInteractionSlugs.length > 0 &&
          !relevantInteractionSlugs.includes(detail.interactionSlug)
        ) {
          processedIdsRef.current.add(entry.id);
          return;
        }

        const eventName =
          entry.type === "interaction_unlocked"
            ? CUSTOM_EVENTS.INTERACTION_UNLOCKED
            : CUSTOM_EVENTS.INTERACTION_COMPLETED;

        window.dispatchEvent(new CustomEvent(eventName, { detail }));
      } else if (isRelevantGateCompletedEntry(entry)) {
        const gateSlug = entry.slug as keyof typeof GATE_TO_FLAG_MAP;
        if (
          relevantGateSlugs.length > 0 &&
          !relevantGateSlugs.includes(gateSlug)
        ) {
          processedIdsRef.current.add(entry.id);
          return;
        }
        const detail: GateCompletedEventDetail = {
          roundSlug,
          gateSlug,
          title: entry.title,
          storyFlag: GATE_TO_FLAG_MAP[gateSlug],
        };
        window.dispatchEvent(
          new CustomEvent(CUSTOM_EVENTS.GATE_COMPLETED, { detail }),
        );
      } else if (isRoundUnlockedEntry(entry)) {
        window.dispatchEvent(
          new CustomEvent(CUSTOM_EVENTS.ROUND_UNLOCKED, {
            detail: {
              roundSlug: entry.slug,
              title: entry.title,
            },
          }),
        );
      } else if (isSpecificPuzzleUnlockedEntry(entry)) {
        window.dispatchEvent(
          new CustomEvent(CUSTOM_EVENTS.PUZZLE_UNLOCKED, {
            detail: {
              puzzleSlug: entry.slug,
              title: entry.title,
            },
          }),
        );
      } else if (isPuzzleProgressEntry(entry)) {
        window.dispatchEvent(
          new CustomEvent(CUSTOM_EVENTS.TEAM_STATE_UPDATED, {
            detail: {
              puzzleSlug: entry.slug,
              title: entry.title,
            },
          }),
        );
      }

      processedIdsRef.current.add(entry.id);
    });
  }, [activityLog, roundSlug]);

  return null;
};

export default InteractionStateManager;
