import { NUM_FEEDERS_BY_ZONE } from "@hunt/hunt-data";
import { type TeamHuntState } from "@hunt/public-client";
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { getPuzzleMetadata } from "../../client/puzzle_metadata";
import {
  PhaserGame,
  type IRefPhaserGame,
} from "../../rounds/overworld/gameworld/PhaserGame";
import { type ROUND_TO_INTERACTION_START } from "../../rounds/overworld/gameworld/common/constants";
import { DataManager } from "../../rounds/overworld/gameworld/common/data-manager";
import {
  CUSTOM_EVENTS,
  EVENT_BUS,
} from "../../rounds/overworld/gameworld/common/event-bus";
import { useInteractionStateFromLocalStorage } from "../../rounds/overworld/gameworld/gameworldLocalState";
import type { SceneLoader } from "../../rounds/overworld/gameworld/scene-loaders/types";
import type { InteractionState } from "../../rounds/overworld/gameworld/types";
import type { BaseTaskDisplay, PuzzleSummary } from "../../rounds/types";
import { IS_STATIC_SITE } from "../../utils/staticSite";
import { usePuzzleState } from "../PuzzleAndTaskDisplay/PuzzleCard";
import { PuzzleUnlockModal } from "../PuzzleUnlockModal";
import { TeamStateProvider } from "../TeamStateProvider";
import {
  applySolvedMapToTeamState,
  useSolvedPuzzlesState,
} from "../puzzleSolveLocalState";
import InteractionStateManager from "./InteractionStateManager";

export function gameworldState(teamState: TeamHuntState): InteractionState {
  // Convert hunt state interactions to gameworld interactions
  const interactions: Record<
    string,
    {
      title: string;
      state: "unlocked" | "running" | "completed";
      result?: string;
      virtual: boolean;
    }
  > = {};

  const gates: InteractionState["gates"] = {};
  const satisfiedGates = new Set(teamState.gates_satisfied ?? []);

  Object.entries(teamState.rounds).forEach(([_roundSlug, round]) => {
    if (round.interactions) {
      Object.entries(round.interactions).forEach(
        ([interactionId, interaction]) => {
          interactions[interactionId] = {
            title: interaction.title,
            state: interaction.state,
            result: interaction.result,
            virtual: interaction.virtual,
          };
        },
      );
    }

    (round.gates ?? []).forEach((gateSlug) => {
      gates[gateSlug] = {
        satisfied: satisfiedGates.has(gateSlug),
      };
    });
  });

  return {
    epoch: teamState.epoch,
    interactions,
    gates,
  };
}

type GameworldRoundSlug = keyof typeof ROUND_TO_INTERACTION_START;

type GameworldZoneClientProps<RoundState extends { epoch: number }> = {
  roundSlug: GameworldRoundSlug;
  initialState: RoundState;
  initialTeamState: TeamHuntState;
  sceneLoader?: SceneLoader;
  render: (args: {
    state: RoundState;
    teamState: TeamHuntState;
    gameNode: React.ReactNode;
    roundSlug: string;
  }) => React.ReactElement;
};

export default function GameworldZoneClient<
  RoundState extends { epoch: number },
>(props: GameworldZoneClientProps<RoundState>) {
  return <GameworldZoneClientInner {...props} />;
}

function GameworldZoneClientInner<RoundState extends { epoch: number }>({
  roundSlug,
  initialState,
  initialTeamState,
  sceneLoader,
  render,
}: GameworldZoneClientProps<RoundState>) {
  const [hasHydrated, setHasHydrated] = useState(false);
  const { solvedMap } = useSolvedPuzzlesState();

  const teamState = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return initialTeamState;
    }
    const effectiveSolvedMap = hasHydrated ? solvedMap : {};
    return applySolvedMapToTeamState(initialTeamState, effectiveSolvedMap);
  }, [hasHydrated, initialTeamState, solvedMap]);

  const state = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return initialState;
    }
    const typedState = initialState as unknown as {
      puzzles: PuzzleSummary[];
      tasks: BaseTaskDisplay[];
      all_feeders_discovered: boolean;
      epoch: number;
    };

    const puzzles = typedState.puzzles.map((puzzle) => {
      const puzzleState = teamState.puzzles[puzzle.slug];
      if (!puzzleState) {
        return puzzle;
      }
      const nextState =
        puzzleState.locked === "unlockable" ? "unlockable" : "unlocked";
      return {
        ...puzzle,
        state: nextState,
        answer: puzzleState.answer ?? puzzle.answer,
      };
    });

    const tasks = typedState.tasks.map((task) => {
      const puzzleState = teamState.puzzles[task.slug];
      if (!puzzleState) {
        return task;
      }
      return {
        ...task,
        state: puzzleState.locked === "unlocked" ? "unlocked" : "locked",
        answer: puzzleState.answer ?? task.answer,
        solved: Boolean(puzzleState.solved),
        prize: puzzleState.prize ?? task.prize,
        taskSubmissionState:
          puzzleState.task_submission_state ?? task.taskSubmissionState,
      };
    });

    const totalFeeders =
      NUM_FEEDERS_BY_ZONE[roundSlug as keyof typeof NUM_FEEDERS_BY_ZONE] ?? 0;
    const discoveredFeeders = puzzles.filter(
      (puzzle) => puzzle.is_overworld_feeder,
    ).length;
    const allFeedersDiscovered =
      totalFeeders > 0
        ? discoveredFeeders >= totalFeeders
        : typedState.all_feeders_discovered;

    return {
      ...typedState,
      epoch: teamState.epoch,
      puzzles,
      tasks,
      all_feeders_discovered: allFeedersDiscovered,
    } as unknown as RoundState;
  }, [initialState, roundSlug, teamState]);
  const teamStateStableRef = useRef<TeamHuntState>(initialTeamState);
  const serverInteractionState = gameworldState(teamState);
  const localStorageInteractionState = useInteractionStateFromLocalStorage();
  const interactionState = IS_STATIC_SITE
    ? localStorageInteractionState
    : serverInteractionState;
  const interactionStateStableRef = useRef<InteractionState>(interactionState);
  const gameRef = useRef<IRefPhaserGame | null>(null);
  const dataManagerRef = useRef<DataManager>();
  if (!dataManagerRef.current) {
    dataManagerRef.current = new DataManager();
  }
  const dataManager = dataManagerRef.current;

  teamStateStableRef.current = teamState;
  interactionStateStableRef.current = interactionState;

  useEffect(() => {
    // Ensure SSR markup matches client before showing the game wrapper.
    setHasHydrated(true);
  }, []);

  const gameNode = useMemo(() => {
    if (!hasHydrated) {
      return null;
    }
    return (
      <PhaserGame
        ref={gameRef}
        teamState={teamStateStableRef.current}
        interactionState={interactionStateStableRef.current}
        dataManager={dataManager}
        roundSlug={roundSlug}
        sceneLoader={sceneLoader}
      />
    );
  }, [dataManager, hasHydrated, roundSlug, sceneLoader]);

  useEffect(() => {
    // TODO: update Phaser game when interaction state changes
  }, [interactionState]);

  useEffect(() => {
    const game = gameRef.current?.game;
    if (!game) {
      return;
    }
    game.registry.set("teamState", teamState);
  }, [teamState]);

  useEffect(() => {
    const updateTeamStateRegistry = () => {
      const game = gameRef.current?.game;
      if (!game) {
        return;
      }

      game.registry.set("teamState", teamStateStableRef.current);
    };

    window.addEventListener(
      CUSTOM_EVENTS.TEAM_STATE_UPDATED,
      updateTeamStateRegistry,
    );

    return () => {
      window.removeEventListener(
        CUSTOM_EVENTS.TEAM_STATE_UPDATED,
        updateTeamStateRegistry,
      );
    };
  }, []);

  // Handle puzzle link clicks from gameworld
  const [activePuzzleSlug, setActivePuzzleSlug] = useState<string | null>(null);
  const [puzzleTitle, setPuzzleTitle] = useState<string>("");
  const [puzzleDesc, setPuzzleDesc] = useState<string | undefined>(undefined);
  const [isPuzzleInfoLoading, setIsPuzzleInfoLoading] =
    useState<boolean>(false);
  const [physicalPresenceRequirement, setPhysicalPresenceRequirement] =
    useState<
      | "required"
      | "required_with_pickup"
      | "recommended"
      | "recommended_with_pickup"
      | undefined
    >(undefined);
  const [nsfw, setNsfw] = useState<boolean | undefined>(undefined);
  const unlockModalRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const handlePuzzleLinkClick = (data: { slug: string; url: string }) => {
      setActivePuzzleSlug(data.slug);
      setPuzzleTitle("");
      setPuzzleDesc(undefined);
      setPhysicalPresenceRequirement(undefined);
      setNsfw(undefined);
      setIsPuzzleInfoLoading(true);

      const metadata = getPuzzleMetadata(data.slug);
      if (metadata) {
        setPuzzleTitle(metadata.title || data.slug);
        setPuzzleDesc(metadata.desc);
        setPhysicalPresenceRequirement(metadata.physical_presence_requirement);
        setNsfw(metadata.nsfw);
      } else {
        setPuzzleTitle(data.slug);
      }

      setIsPuzzleInfoLoading(false);
    };

    EVENT_BUS.on(CUSTOM_EVENTS.PUZZLE_LINK_CLICKED, handlePuzzleLinkClick);

    return () => {
      EVENT_BUS.off(CUSTOM_EVENTS.PUZZLE_LINK_CLICKED, handlePuzzleLinkClick);
    };
  }, []);

  // Show modal when activePuzzleSlug changes and puzzle exists
  useEffect(() => {
    if (activePuzzleSlug && teamState.puzzles[activePuzzleSlug]) {
      // Use requestAnimationFrame to ensure the modal is rendered
      requestAnimationFrame(() => {
        unlockModalRef.current?.showModal();
      });
    }
  }, [activePuzzleSlug, teamState.puzzles]);

  const dismissModal = useCallback(() => {
    unlockModalRef.current?.close();
    setActivePuzzleSlug(null);
    setPuzzleTitle("");
    setPuzzleDesc(undefined);
    setPhysicalPresenceRequirement(undefined);
    setIsPuzzleInfoLoading(false);
  }, []);

  // Get puzzle state for the active puzzle
  // Always call usePuzzleState to avoid hooks order violation
  const epoch = teamState.epoch;
  const puzzle = activePuzzleSlug
    ? teamState.puzzles[activePuzzleSlug]
    : undefined;
  const puzzleStateHandle = usePuzzleState(epoch, {
    slug: activePuzzleSlug ?? "",
    title: puzzleTitle || (activePuzzleSlug ?? ""),
    state: puzzle?.locked ?? "locked",
    answer: puzzle?.answer,
    solved: puzzle?.solved,
    desc: puzzleDesc,
    unlock_cost: puzzle?.unlock_cost,
    is_overworld_feeder: puzzle?.is_overworld_feeder ?? false,
  });

  return (
    <TeamStateProvider teamState={teamState}>
      <InteractionStateManager roundSlug={roundSlug} />
      {!IS_STATIC_SITE && activePuzzleSlug && puzzle && (
        <PuzzleUnlockModal
          ref={unlockModalRef}
          stateHandle={puzzleStateHandle}
          onDismiss={dismissModal}
          cost={puzzleStateHandle[0].unlock_cost ?? 1}
          isLoading={isPuzzleInfoLoading}
          physicalPresenceRequirement={physicalPresenceRequirement}
          nsfw={nsfw}
        />
      )}
      {render({
        state,
        teamState,
        gameNode,
        roundSlug,
      })}
    </TeamStateProvider>
  );
}
