import { PUZZLES, getTasks } from "@hunt/puzzles";
import type { PhysicalPresenceRequirement } from "./all_puzzles_types";

export type PuzzleMetadata = {
  title: string;
  desc?: string;
  nsfw?: boolean;
  physical_presence_requirement?: PhysicalPresenceRequirement;
};

type PuzzleMetadataSource = {
  slug: string;
  title: string;
  initial_description?: string;
  content?: {
    nsfw?: boolean;
    physical_presence_requirement?: PhysicalPresenceRequirement;
  };
};

const puzzleMetadataMap = new Map<string, PuzzleMetadata>();

const addPuzzleMetadata = (puzzle: PuzzleMetadataSource) => {
  puzzleMetadataMap.set(puzzle.slug, {
    title: puzzle.title,
    desc: puzzle.initial_description,
    nsfw: puzzle.content?.nsfw,
    physical_presence_requirement:
      puzzle.content?.physical_presence_requirement,
  });
};

Object.values(PUZZLES).forEach(addPuzzleMetadata);
Object.values(getTasks()).forEach((puzzle) => {
  if (!puzzleMetadataMap.has(puzzle.slug)) {
    addPuzzleMetadata(puzzle);
  }
});

export const getPuzzleMetadata = (slug: string): PuzzleMetadata | undefined =>
  puzzleMetadataMap.get(slug);

export const getPuzzleMetadataMap = (): Map<string, PuzzleMetadata> =>
  puzzleMetadataMap;
